def before(para,text,style=None):
 q=para.insert_paragraph_before(text)
 if style:q.style=style
 return q
def section_after(d,needle,title,texts):
 para=next(x for x in d.paragraphs if needle in x.text)
 before(para,title,'Heading 1')
 for text in texts:before(para,text)

