for f in O.glob('*.docx'):
 d=Document(f);norm(d)
 for sec in d.sections:sec.top_margin=Twips(850);sec.bottom_margin=Twips(850)
 for s in d.styles:
  if s.type==1:
   s.font.name='Arial';s.font.size=Pt(10 if s.name=='Normal' else 15 if s.name=='Title' else 11);s.font.color.rgb=RGBColor(0,0,0)
   s.paragraph_format.space_after=Pt(6)
   if s._element.pPr is not None:
    for x in list(s._element.pPr.findall(qn('w:pBdr'))):s._element.pPr.remove(x)
 for para in d.paragraphs:
  if re.match(r'^[1-5]\. ',para.text):para.text=re.sub(r'^([1-5])\. ',r'\1 ',para.text);para.style='Heading 1'
  if para.text.isupper() and len(para.text)>15 and not para.text.startswith('{{'):para.style='Title'
  for run in para.runs:
   run.font.name='Arial';run.font.size=Pt(13 if para.style.name=='Title' else 11 if para.style.name.startswith('Heading') else 10)
   if para.style.name=='Title':run.font.bold=True
 for x in d._element.iter(qn('w:color')):x.attrib.clear();x.set(qn('w:val'),'000000')
 for table in d.tables:
  if len(table.columns)==3:
   widths=[2700,3100,4066]
   for col,w in zip(table.columns,widths):col.width=Twips(w)
   for row in table.rows:
    for cell,w in zip(row.cells,widths):elem(cell._tc.get_or_add_tcPr(),'w:tcW',{'w:type':'dxa','w:w':w})
  if len(table.columns)>1:
   for c in table.rows[0].cells:
    elem(c._tc.get_or_add_tcPr(),'w:shd',{'w:fill':'EFEFEF'})
    for para in c.paragraphs:
     for run in para.runs:run.font.bold=True
  following=table._element.getnext()
  if following is not None and following.tag==qn('w:p'):
   from docx.text.paragraph import Paragraph
   Paragraph(following,d).paragraph_format.space_before=Pt(6)
 if f.name.startswith('01'):
  next(x for x in d.paragraphs if x.text=='Поля и итог позиции').paragraph_format.page_break_before=True
 for sec in d.sections:
  for para in sec.footer.paragraphs:
   para.text='НА СТОРОНЕ ПОДРЯДЧИКА  /  P10  /  Редакция 31.10.2026'
   for run in para.runs:run.font.name='Arial';run.font.size=Pt(8);run.font.color.rgb=RGBColor(0,0,0)
 d.save(f)
print('Built',len(list(O.glob('*.docx'))),'Word files')
